		if ($passpol_info =~ /Account Lockout Threshold/) {
			print $passpol_info;

item.aggregated_output:
			print $passpol_info;
		} elsif ($passpol_info =~ /Error Getting Password Policy: Connect error/) {
			print_error("Can't connect to host with supplied credentials.\n");
