			foreach my $groupname (keys %rid_of_group) {
				print_plus("Getting detailed info for group $groupname (RID: " . $rid_of_group{$groupname} . ")\n");
				get_group_details_from_rid($rid_of_group{$groupname});
			}
		}
	}
