+			? $global_time_budget - ($now - $batch_start)
+			: undef;
+		my $can_retry = $job->{attempts_left} > 1
+			&& !$auth_failure
+			&& (!defined($remaining_budget) || $remaining_budget > 0);
+
+		if ($exit_code == 0 && !$was_timeout) {
+			print deduplicate_output($output);
+			$succeeded++;
+			return;
+		}
+
+		if ($auth_failure) {
