+				unlink $output_file;
+				die "ERROR: Unable to fork a host worker: $!\n";
+			}
+			if ($pid == 0) {
+				run_host_worker($job->{target}, $output_file);
+			}
+			$job->{output_file} = $output_file;
+			$job->{started_at} = Time::HiRes::time();
+			$active{$pid} = $job;
+			$next_start_at = Time::HiRes::time() + $rate_interval if $rate_interval > 0;
+			$launched = 1;
+		}
