+
+sub run_host_worker {
+	my ($target, $output_file) = @_;
+	setpgrp(0, 0);
+	open(STDOUT, '>', $output_file) or exit 1;
+	open(STDERR, '>&', STDOUT) or exit 1;
+	select(STDOUT);
+	$| = 1;
+	$global_target = $target;
+	my $status = 0;
+	eval {
+		run_target();
