	my ($status, $output, $state) = run_enum(
		argv => [
			'-U',
			'--threads', '2',
			'--rate', '20',
			'--retries', '2',
			'--retry-delay', '0.01',
			'--targets', '10.20.0.1,10.20.0.2',
		],
		env => {
